((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"year":2007,"id":"2007-7-8","grades":[7,8],"label":"7–8 классы","tasksUrl":"assets/kenguru/kenguru_2007_class_7-8.pdf","answersUrl":"assets/kenguru/kenguru_2007_answers.pdf","solutionUrl":null,"answerLetters":"ABCDE","cards":[{"number":1,"title":"Буквы слова КЕНГУРУ","question":"В слове КЕНГУРУ четыре буквы стёрли, а остальные записали в обратном порядке. Что могло получиться?","options":[{"text":"ГЕН"},{"text":"РЕГ"},{"text":"УЕК"},{"text":"РГУ"},{"text":"УУР"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Прочитаем любой предложенный результат справа налево. Полученные буквы должны идти в исходном слове слева направо."},{"title":"Ответ","text":"Из букв слова КЕНГУРУ можно выбрать по порядку К, Е, У. После разворота получается УЕК. К в конце слова УЕК соответствует первой букве исходного слова."}]},{"number":2,"title":"Отрицательное число k","question":"k — целое отрицательное число. Какое число наибольшее?","options":[{"text":"k − 1"},{"text":"2k"},{"text":"k − 2"},{"text":"6k − 2"},{"text":"−2k"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"При отрицательном k числа k − 1, 2k, k − 2 и 6k − 2 отрицательны."},{"title":"Ответ","text":"У произведения −2k оба множителя отрицательны, поэтому оно положительно и больше остальных чисел."}]},{"number":3,"title":"Внешние углы треугольника","question":"Чему равна сумма всех шести внешних углов треугольника?","options":[{"text":"180°"},{"text":"360°"},{"text":"540°"},{"text":"720°"},{"text":"зависит от треугольника"}],"condition":{"src":"assets/grades-7-8/2007/task-03.svg","width":294,"height":183,"alt":"Треугольник с продолжениями сторон и выделенными внешними углами"},"answer":3,"points":3,"review":[{"title":"Решение","text":"При каждой вершине два внешних угла. Каждый из них вместе с внутренним образует развёрнутый угол."},{"title":"Ответ","text":"Сумма по одному внешнему углу при каждой вершине — 3 · 180° − 180° = 360°. Все шесть в сумме дают 2 · 360° = 720°."}]},{"number":4,"title":"Разность палиндромов","question":"Число-палиндром — это число, которое не меняется при записывании его цифр в обратном порядке. Чему равна разность между самым большим шестизначным палиндромом и самым маленьким пятизначным палиндромом?","options":[{"text":"989989"},{"text":"988888"},{"text":"989998"},{"text":"998998"},{"text":"999988"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Самое большое шестизначное число 999999 является палиндромом."},{"title":"Решение","text":"Самый маленький пятизначный палиндром должен начинаться и заканчиваться единицей. Остальные цифры можно взять нулями. Получаем 10001."},{"title":"Ответ","text":"Вычитаем 999999 − 10001 = 989998."}]},{"number":5,"title":"Горизонтальный отрезок","question":"Точки A (2006, 2007), B (2007, 2006), C (−2006, −2007), D (2006, −2007) и E (2007, −2006) отмечены на координатной плоскости. Какой из следующих отрезков горизонтальный?","options":[{"text":"AD"},{"text":"BE"},{"text":"BC"},{"text":"CD"},{"text":"AB"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"Горизонтальный отрезок соединяет точки на одной высоте, у которых совпадают вторые координаты."},{"title":"Ответ","text":"Вторые координаты C и D равны −2007. Значит, горизонтален отрезок CD."}]},{"number":6,"title":"Симметрия квадратиков","question":"Какое наименьшее количество маленьких квадратиков нужно ещё закрасить, чтобы у рисунка появилась ось симметрии?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":{"src":"assets/grades-7-8/2007/task-06.svg","width":213,"height":216,"alt":"Квадратное поле из наклонных клеток с чёрными и белыми квадратиками"},"answer":1,"points":3,"review":[{"title":"Решение","text":"Внешний контур допускает четыре оси. Для каждой оси найдём закрашенные клетки, отражения которых остаются белыми."},{"title":"Ответ","text":"Для вертикальной оси нужны 3 клетки, для горизонтальной — 5, для диагоналей — 5 и 4. Закрасим отражения трёх клеток для вертикальной оси."}]},{"number":7,"title":"Примета про бегемотов","question":"Народная примета племени Ых-Ух гласит: «Если бегемоты ныряют глубоко, то будет дождь». Это означает, что","options":[{"text":"если будет дождь, то бегемоты должны нырять глубоко"},{"text":"если в местности нет бегемотов, то там не бывает дождя"},{"text":"если бегемоты сидят на берегу, то дождя не ожидается"},{"text":"если бегемоты ныряют неглубоко, то дождя не будет"},{"text":"если дождь не ожидается, а бегемоты ныряют, то они ныряют неглубоко"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Примета обещает дождь при любом глубоком нырянии. О других причинах дождя в ней ничего не сказано."},{"title":"Ответ","text":"Если дождя не ожидается, глубокое ныряние исключено. Если бегемоты всё-таки ныряют, то неглубоко."}]},{"number":8,"title":"Квадрат в квадрате","question":"Вершины маленького квадрата лежат на сторонах большого. Найдите площадь меньшего квадрата.","options":[{"text":"16"},{"text":"28"},{"text":"34"},{"text":"36"},{"text":"64"}],"condition":{"src":"assets/grades-7-8/2007/task-08.svg","width":261,"height":186,"alt":"Квадрат внутри квадрата с отрезками длиной 3 и 5"},"answer":2,"points":3,"review":[{"title":"Решение","text":"В углах большого квадрата остаются четыре равных прямоугольных треугольника. Их гипотенузы равны как стороны малого квадрата. Острые углы у соседних треугольников равны попарно, поскольку стороны обоих квадратов перпендикулярны."},{"title":"Решение","text":"У треугольника в верхнем правом углу вертикальный катет равен 5, а горизонтальный — 3, как вертикальный катет соседнего треугольника. Его гипотенуза является стороной малого квадрата."},{"title":"Ответ","text":"По теореме Пифагора площадь малого квадрата равна 3² + 5² = 34."}]},{"number":9,"title":"Делитель суммы степеней","question":"Чему равен наименьший простой делитель числа 3¹¹ + 5¹³?","options":[{"text":"2"},{"text":"3"},{"text":"5"},{"text":"7"},{"text":"13"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"Степени нечётных чисел 3 и 5 нечётны. Сумма двух нечётных чисел чётна."},{"title":"Ответ","text":"Она делится на 2, а 2 — наименьшее простое число."}]},{"number":10,"title":"Стрелки в 17:30","question":"Чему равен угол между часовой и минутной стрелками в 17:30?","options":[{"text":"10°"},{"text":"15°"},{"text":"25°"},{"text":"30°"},{"text":"40°"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"В половине шестого минутная стрелка стоит на цифре 6, а часовая — на середине между отметками 5 и 6."},{"title":"Ответ","text":"Расстояние между соседними часовыми отметками равно 360° : 12 = 30°. Половина этого угла равна 15°."}]},{"number":11,"title":"Степени четырёх и восьми","question":"Чтобы получить 8⁸, нужно 4⁴ возвести в","options":[{"text":"квадрат"},{"text":"куб"},{"text":"четвёртую степень"},{"text":"восьмую степень"},{"text":"шестнадцатую степень"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Выразим основания как степени двойки: 8 = 2³ и 4 = 2²."},{"title":"Ответ","text":"Получаем 8⁸ = 2²⁴ и 4⁴ = 2⁸. Куб числа 4⁴ равен 2²⁴."}]},{"number":12,"title":"Ломаная из квадратов","question":"Отрезок AB пересечён ломаной линией, как показано на рисунке. При этом получилось 5 квадратов. Чему равна длина ломаной AA₁A₂…A₁₀B, если длина AB равна 10 см?","options":[{"text":"30 см"},{"text":"40 см"},{"text":"50 см"},{"text":"60 см"},{"text":"80 см"}],"condition":{"src":"assets/grades-7-8/2007/task-12.svg","width":390,"height":234,"alt":"Ломаная AA₁A₂…A₁₀B и пять квадратов на отрезке AB"},"answer":0,"points":4,"review":[{"title":"Решение","text":"Отрезок AB состоит из пяти сторон квадратов, идущих подряд."},{"title":"Ответ","text":"При обходе по ломаной каждая из этих сторон заменяется тремя равными ей сторонами квадрата. Поэтому длина ломаной равна 3 · 10 = 30 см."}]},{"number":13,"title":"Общий множитель","question":"Чему равно a²b − ab + a²c − ac, если a = 5, b + c = 6?","options":[{"text":"120"},{"text":"125"},{"text":"180"},{"text":"240"},{"text":"невозможно определить"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Решение","text":"Сначала вынесем a² − a из обеих пар: a²b − ab + a²c − ac = (a² − a)(b + c)."},{"title":"Ответ","text":"Подставим известные числа: (25 − 5) · 6 = 120."}]},{"number":14,"title":"Объёмная фигурка","question":"На каких из рисунков W, X, Y и Z изображена та же фигурка, что и на рисунке в рамке?","options":[{"text":"только W"},{"text":"только Y"},{"text":"W и Y"},{"text":"W, X и Y"},{"text":"ни на одном"}],"condition":{"src":"assets/grades-7-8/2007/task-14.svg","width":687,"height":459,"alt":"Фигурки W, X, Y и Z для сравнения и образец в рамке"},"answer":2,"points":4,"review":[{"title":"Решение","text":"Найдём самый длинный прямой участок и посмотрим, в какие стороны уходят выступы на его концах. Затем сравним направления коротких загибов после этих выступов."},{"title":"Ответ","text":"У W и Y эти направления совпадают с образцом после поворота. У X порядок поворотов отражён, а у Z иначе направлен один из концевых загибов."}]},{"number":15,"title":"Число в квадрате","question":"При возведении в квадрат","options":[{"text":"число всегда увеличивается"},{"text":"число всегда уменьшается"},{"text":"число всегда изменяется"},{"text":"изменяются все числа, кроме одного"},{"text":"изменяются все числа, кроме двух"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Число x сохраняется при возведении в квадрат, когда x² = x."},{"title":"Ответ","text":"Получаем x(x − 1) = 0. Подходят ровно два числа, 0 и 1."}]},{"number":16,"title":"Два правильных треугольника","question":"ABC и CDE — равные правильные треугольники. Чему равен угол ABD, если угол ACD равен 80°?","options":[{"text":"25°"},{"text":"30°"},{"text":"35°"},{"text":"40°"},{"text":"45°"}],"condition":{"src":"assets/grades-7-8/2007/task-16.svg","width":366,"height":222,"alt":"Равные треугольники ABC и CDE и отрезок BD"},"answer":3,"points":4,"review":[{"title":"Решение","text":"По рисунку ∠BCD = ∠BCA + ∠ACD = 60° + 80° = 140°."},{"title":"Решение","text":"Стороны BC и CD равны, поэтому ∠CBD = (180° − 140°) : 2 = 20°."},{"title":"Ответ","text":"Луч BD лежит внутри угла ABC. Значит, ∠ABD = 60° − 20° = 40°."}]},{"number":17,"title":"Квадраты до 10000","question":"Сколько процентов среди целых чисел от 1 до 10000 составляют квадраты?","options":[{"text":"0,5%"},{"text":"1%"},{"text":"2,5%"},{"text":"2%"},{"text":"20%"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"Наименьший квадрат — 1², наибольший — 100² = 10000. Поэтому квадратов ровно 100."},{"title":"Ответ","text":"Доля 100 из 10000 равна 1%."}]},{"number":18,"title":"Знаки чисел a и b","question":"Числа a и b таковы, что a > 1/b и 1/a > b. Тогда","options":[{"text":"ab > 1"},{"text":"a < 0"},{"text":"b > a"},{"text":"b < 0"},{"text":"такого не бывает"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Предположим, что b положительно. Тогда a > 1/b > 0, поэтому обе части каждого неравенства можно умножить на соответствующий положительный знаменатель."},{"title":"Ответ","text":"Первое даёт ab > 1, а второе ab < 1. Это противоречие. b не может быть нулём, так что b < 0."}]},{"number":19,"title":"Закрашенная часть квадрата","question":"Отрезки OA, OB, OC и OD проведены из центра O квадрата KLMN так, что OA ⟂ OB, OC ⟂ OD. Сторона квадрата KLMN равна 2. Чему равна площадь закрашенной фигуры?","options":[{"text":"1"},{"text":"2"},{"text":"2,5"},{"text":"2,25"},{"text":"зависит от выбора точек B и C"}],"condition":{"src":"assets/grades-7-8/2007/task-19.svg","width":246,"height":240,"alt":"Квадрат KLMN с центром O и двумя закрашенными секторами"},"answer":1,"points":4,"review":[{"title":"Решение","text":"Поворот квадрата на 90° вокруг O сохраняет квадрат. Четыре сектора, полученные последовательными поворотами сектора AOB, имеют одинаковые площади и покрывают квадрат."},{"title":"Ответ","text":"То же верно для сектора COD, поэтому каждый из двух закрашенных секторов занимает четверть квадрата. Их общая площадь — 2."}]},{"number":20,"title":"Длины сторон треугольника","question":"Отрезки длины 1, k, 2k являются длинами сторон треугольника в том и только в том случае, когда","options":[{"text":"0 < k < 1"},{"text":"k > 1"},{"text":"0 < k"},{"text":"k > 1/3"},{"text":"1/3 < k < 1"}],"condition":null,"answer":4,"points":4,"review":[{"title":"Решение","text":"Неравенство треугольника для стороны 1 требует 1 < k + 2k, то есть k > 1/3."},{"title":"Ответ","text":"Для стороны 2k получаем 2k < 1 + k, то есть k < 1. Для стороны k неравенство уже выполняется. Получаем 1/3 < k < 1."}]},{"number":21,"title":"Сумма и произведение","question":"Сумма трёх чисел −1, −2, −3 равна их произведению. Сколько всего троек целых чисел обладают таким свойством?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"6"},{"text":"бесконечно много"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Возьмём тройку из нуля, целого числа t и противоположного ему числа −t. Её сумма и произведение оба равны нулю."},{"title":"Ответ","text":"Подходят все положительные целые t, поэтому таких троек бесконечно много."}]},{"number":22,"title":"Треугольники и периметр","question":"Два равных правильных треугольника приложили друг к другу и продлили их стороны, как показано на рисунке. Периметр четырёхугольника ABCD равен 8. Чему равна длина отрезка PC?","options":[{"text":"0,5"},{"text":"1"},{"text":"2"},{"text":"4"},{"text":"невозможно определить"}],"condition":{"src":"assets/grades-7-8/2007/task-22.svg","width":312,"height":195,"alt":"Два правильных треугольника с точками A, B, C, D, P и Q"},"answer":2,"points":5,"review":[{"title":"Решение","text":"Обозначим через s сторону каждого большого треугольника. В частности, AQ = PC = s. Малый верхний треугольник с основанием BP тоже правильный, поэтому AB = s − BP."},{"title":"Решение","text":"Четырёхугольник ABCD — параллелограмм: стороны попарно параллельны по рисунку и углам 60°. Его полупериметр AB + BC = (s − BP) + (BP + s) = 2s."},{"title":"Ответ","text":"Половина периметра равна 4, откуда PC = s = 2."}]},{"number":23,"title":"Остатки по кругу","question":"По кругу написаны 5 целых чисел, причём сумма никаких двух соседних и никаких трёх идущих подряд чисел не делится на 3. Сколько из написанных чисел делится на 3?","options":[{"text":"0"},{"text":"1"},{"text":"2"},{"text":"3"},{"text":"невозможно определить"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Рассмотрим остатки 0, 1, 2. Два нуля не могут стоять рядом. Соседние ненулевые остатки должны быть одинаковыми, поскольку 1 + 2 делится на 3."},{"title":"Решение","text":"Три ненулевых остатка подряд невозможны: они были бы одинаковыми и их сумма делилась бы на 3. Без нулей или с одним нулём такая тройка возникла бы."},{"title":"Ответ","text":"Три нуля на круге из пяти мест неизбежно дали бы соседнюю пару. Значит, нулей ровно два. Например, подходит круг 0, 1, 0, 1, 1."}]},{"number":24,"title":"Дуги на кафельной плитке","question":"Имеются одинаковые плитки кафеля с нарисованными на них дугами. Длина каждой дуги равна 1, а концы дуг — середины сторон плитки. Из 16 таких плиток надо сложить квадрат. Некоторые дуги будут соединяться между собой, образуя более длинные кривые. Какова наибольшая возможная длина такой кривой?","options":[{"text":"18"},{"text":"20"},{"text":"21"},{"text":"22"},{"text":"24"}],"condition":{"src":"assets/grades-7-8/2007/task-24.svg","width":159,"height":153,"alt":"Плитка с двумя дугами, соединяющими соседние стороны"},"answer":3,"points":5,"review":[{"title":"Решение","text":"На границе квадрата 16 концов дуг, значит, есть 8 незамкнутых кривых. Среди семи кривых, отличных от выбранной самой длинной, максимум четыре могут иметь длину 1: для этого нужна угловая плитка."},{"title":"Решение","text":"На остальные из этих семи кривых уходит не меньше двух дуг на каждую. Всего вне самой длинной кривой требуется хотя бы 4 + 2 · 3 = 10 дуг, поэтому её длина не превосходит 32 − 10 = 22."},{"title":"Ответ","text":"Обозначим исходную плитку через 0, повёрнутую на 90° через 1. Подходит раскладка рядами 0001, 1100, 0011, 1010. От верхней стороны второй плитки прослеживается кривая из 22 дуг."}]},{"number":25,"title":"Баллы пяти шалунов","question":"Пять шалунов A, B, C, D и E участвуют в конкурсе «Кенгуру». Шалун A выбирает на все задачи ответ A, B выбирает ответ B и так далее. Все набрали разное количество баллов, и никто не получил ноль баллов. Сколько баллов не мог набрать шалун, занявший среди них первое место, если занявший третье место набрал 36 баллов?","options":[{"text":"38"},{"text":"39"},{"text":"40"},{"text":"41"},{"text":"среди ответов A–D нет верного"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"За каждую задачу получает баллы ровно один шалун. Всего у пятерых 10 · (3 + 4 + 5) = 120 баллов."},{"title":"Решение","text":"Если первый набрал 41, у второго как минимум 37, у третьего 36, у двух последних вместе хотя бы 3 + 4 = 7. Получилось бы как минимум 121 балл."},{"title":"Ответ","text":"Для других предложенных максимумов возможны распределения по баллам (38, 37, 36, 5, 4), (39, 37, 36, 5, 3) и (40, 37, 36, 4, 3). Например, после выдачи последних двух результатов первым троим можно соответственно выдать наборы задач (0,2,6), (1,6,2), (9,1,1) для 38, (0,1,7), (0,8,1), (9,1,1) для 39 и (0,0,8), (0,8,1), (9,1,1) для 40, где тройка указывает числа задач на 3, 4 и 5 баллов."}]},{"number":26,"title":"Суммы цифр при делении","question":"Трёхзначное число поделили на 9. Оказалось, что у частного сумма цифр на 9 меньше суммы цифр исходного числа. Сколько всего таких чисел?","options":[{"text":"1"},{"text":"2"},{"text":"5"},{"text":"6"},{"text":"11"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Пусть частное равно m. Тогда 12 ≤ m ≤ 111. Сумма цифр делимого 9m кратна 9, поэтому сумма цифр m тоже кратна 9. Само m делится на 9."},{"title":"Ответ","text":"Проверим m = 18, 27, 36, 45, 54, 63, 72, 81, 90, 99, 108. Разность сумм цифр равна 9 у 54, 63, 72, 81 и 108. Это даёт пять исходных чисел: 486, 567, 648, 729, 972."}]},{"number":27,"title":"Пять шагов автомата","question":"За один шаг автомат умеет выполнять одну из четырёх операций: либо умножить данное число на 2, либо умножить данное число на 3, либо возвести его в квадрат, либо в куб. Что может получиться после 5 шагов, если начать с числа 15?","options":[{"text":"2⁸ · 3⁵ · 5⁶"},{"text":"2 · 3⁴ · 5²"},{"text":"2⁸ · 3⁴ · 5²"},{"text":"2 · 3² · 5⁶"},{"text":"2⁶ · 3⁶ · 5⁴"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Умножение на 2 или 3 добавляет единицу к соответствующему показателю, а возведение в квадрат удваивает все показатели."},{"title":"Решение","text":"У варианта E верная последовательность такая: умножить на 2, возвести в квадрат, умножить на 6 за два шага (на 2 и на 3), затем снова возвести в квадрат. Показатели при 2, 3 и 5 меняются от (0, 1, 1) через (1, 1, 1), (2, 2, 2), (3, 2, 2), (3, 3, 2) до (6, 6, 4)."},{"title":"Ответ","text":"У A и D показатель при 5 равен 6. Для этого нужны квадрат и куб, которые умножают исходный показатель при 3 хотя бы на 6. У B одно возведение в квадрат, одна операция ×2 после него и не более двух операций ×3, поэтому пяти шагов не набирается. У C показатель при 5 требует одного квадрата. Чтобы показатель при 2 достиг 8, все четыре остальные операции должны быть умножениями на 2 перед квадратом. Тогда показатель при 3 равен 2 вместо 4."}]},{"number":28,"title":"Угол между дугами","question":"Точки P и Q являются центрами окружностей, дуги которых изображены на рисунке. Угол BAC равен 22°. Чему равен угол α?","options":[{"text":"44°"},{"text":"46°"},{"text":"57°"},{"text":"60°"},{"text":"68°"}],"condition":{"src":"assets/grades-7-8/2007/task-28.svg","width":279,"height":171,"alt":"Две дуги с центрами P и Q, треугольник ABC и угол α при C"},"answer":2,"points":5,"review":[{"title":"Решение","text":"Поскольку QA = QP, углы QAP и QPA равны 22°. Тогда центральный угол QPC равен 180° − 22° = 158°."},{"title":"Решение","text":"Точка B лежит на меньшей дуге QC, поэтому вписанный угол QBC равен половине большей дуги: (360° − 158°) : 2 = 101°."},{"title":"Ответ","text":"Угол ABC равен QBC. Из треугольника ABC получаем α = 180° − 101° − 22° = 57°."}]},{"number":29,"title":"Число делителей","question":"Целое число n имеет два натуральных делителя, а число n + 1 — три натуральных делителя. Сколько натуральных делителей имеет число n + 2?","options":[{"text":"1"},{"text":"2"},{"text":"4"},{"text":"5"},{"text":"ответ зависит от n"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Модуль числа с двумя натуральными делителями прост. Модуль числа с тремя делителями является квадратом простого числа: средний делитель составляет пару с собой. Поэтому модуль числа n + 1 равен p² для простого p."},{"title":"Решение","text":"Если n положительно, то n = (p − 1)(p + 1), поэтому p − 1 = 1, p = 2 и n = 3. Тогда n + 2 = 5."},{"title":"Ответ","text":"Если n отрицательно, то его модуль p² + 1. Для любого нечётного p это чётное число больше 2, поэтому p = 2 и n = −5. Тогда n + 2 = −3. У чисел 5 и −3 ровно по два натуральных делителя."}]},{"number":30,"title":"Прогулка туриста","question":"Турист совершил двухчасовую прогулку. Он сначала шёл по равнине, потом взошёл на вершину горы, а потом вернулся в начало пути: спустился с горы и шёл по равнине. Скорость туриста на подъёме равнялась 3 км/ч, на спуске — 6 км/ч, а по равнине — 4 км/ч. Какой путь он прошёл?","options":[{"text":"6 км"},{"text":"7,5 км"},{"text":"8 км"},{"text":"10 км"},{"text":"невозможно определить"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Если длина подъёма L км, то подъём и спуск вместе заняли L/3 + L/6 = L/2 часа. Пройдено 2L км, что соответствует средней скорости 4 км/ч."},{"title":"Решение","text":"По равнине турист тоже шёл со скоростью 4 км/ч, поэтому средняя скорость за всю прогулку — 4 км/ч."},{"title":"Ответ","text":"За 2 часа турист прошёл 4 · 2 = 8 км."}]}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2007-7-8"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2007] ?? []).find(edition => edition.id === "2007-7-8")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
